// API предполагается value-based: Input/Select/Switch отдают значение, а не событие.
// Если в вашей версии @jinx-ui/react колбэки принимают event — поправьте обработчики.
import { useState, type FormEvent } from 'react';
import {
  Alert,
  Button,
  Form,
  FormField,
  Input,
  Select,
  Stack,
  Switch,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLES: ReadonlyArray<{ value: Role; label: string }> = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function InviteTeammateForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const showError = touched && !isValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      {invited !== null && (
        <Alert
          variant="success"
          dismissible
          onDismiss={() => setInvited(null)}
          title="Приглашение отправлено"
        >
          {invited} получит доступ с ролью «
          {ROLES.find((r) => r.value === role)?.label}».
        </Alert>
      )}

      <Form onSubmit={handleSubmit}>
        <Stack direction="column" gap="var(--jx-space-4)">
          <FormField
            label="Электронная почта"
            htmlFor="invite-email"
            hint="Укажите рабочий адрес — приглашение действует 7 дней."
            error={showError ? 'Введите корректный адрес, например name@example.com' : undefined}
            required
          >
            <Input
              id="invite-email"
              type="email"
              name="email"
              autoComplete="email"
              placeholder="name@example.com"
              value={email}
              invalid={showError}
              onChange={setEmail}
              onBlur={() => setTouched(true)}
            />
          </FormField>

          <FormField label="Роль в команде" htmlFor="invite-role">
            <Select
              id="invite-role"
              name="role"
              value={role}
              options={ROLES}
              onChange={(value: Role) => setRole(value)}
            />
          </FormField>

          <Switch
            id="invite-notify"
            name="notify"
            checked={notify}
            onChange={setNotify}
            label="Отправить уведомление на почту"
          />

          <Stack direction="row" justify="end">
            <Button type="submit" variant="primary" disabled={!isValid}>
              Отправить приглашение
            </Button>
          </Stack>
        </Stack>
      </Form>
    </Stack>
  );
}

